from work import *
id='local010'
base='''WITH airports AS (SELECT airport_code,json_extract(city,'$.en') city,CAST(substr(coordinates,2,instr(coordinates,',')-2) AS REAL)*pi()/180 lng,CAST(substr(coordinates,instr(coordinates,',')+1,length(coordinates)-instr(coordinates,',')-1) AS REAL)*pi()/180 lat FROM airports_data), route_rows AS (SELECT f.flight_id,a.city from_city,b.city to_city,a.airport_code dep,b.airport_code arr,2*6371*asin(sqrt(min(1.0,max(0.0,pow(sin((a.lat-b.lat)/2),2)+cos(a.lat)*cos(b.lat)*pow(sin((a.lng-b.lng)/2),2))))) distance FROM flights f JOIN airports a ON f.departure_airport=a.airport_code JOIN airports b ON f.arrival_airport=b.airport_code), pairs AS (SELECT min(from_city,to_city) city1,max(from_city,to_city) city2,avg(distance) distance,count(*) flights FROM route_rows GROUP BY 1,2), bins(bucket) AS (VALUES(0),(1000),(2000),(3000),(4000),(5000),(6000)), counts AS (SELECT bucket,count(p.city1) pair_count FROM bins LEFT JOIN pairs p ON min(6000,cast(p.distance/1000 AS INTEGER)*1000)=bucket GROUP BY bucket) '''
query(id,base+'SELECT * FROM counts','bins.json')
query(id,base+'SELECT count(*) pairs,sum(flights) flights,min(distance),max(distance),sum(city1=city2) same_city_pairs FROM pairs','pair-counts.json')
query(id,base+'SELECT city1,city2,count(*) airport_routes,min(distance),max(distance) FROM (SELECT DISTINCT min(from_city,to_city) city1,max(from_city,to_city) city2,min(dep,arr) dep,max(dep,arr) arr,distance FROM route_rows) GROUP BY 1,2 HAVING count(*)>1 ORDER BY count(*) DESC LIMIT 10','multi-route.json')
query(id,base.replace('min(from_city,to_city) city1,max(from_city,to_city) city2','from_city city1,to_city city2')+'SELECT * FROM counts','directional-bins.json')
query(id,base.replace('FROM route_rows GROUP BY 1,2','FROM (SELECT DISTINCT from_city,to_city,dep,arr,distance FROM route_rows) GROUP BY 1,2').replace(',count(*) flights',',count(*) flights')+'SELECT * FROM counts','route-equal-bins.json')
fields={'population.eligibility':{'value':'All flight records with both airport city and coordinates; no extra state/time restrictions','basis':'request','quote':'all routes between them'},'population.conditions':'n/a','population.time':'n/a','measure.formula':{'value':{'op':'custom','description':'Haversine km R6371 per flight row; normalize unordered city names; mean distance per city pair across all flights; count pairs by lower-bound 1000km bins with capped 6000+; include empty bins; minimum count'},'cite':[{'source':'knowledge:haversine_formula.md','quote':'dividing by the total number of flights between those cities'}]},'grouping':'n/a','selection':'n/a','output':{'value':{'rowMode':'scalar','columns':['fewest_pair_count']},'basis':'request','quote':'how many pairs are there'}}
finish(id,fields,base+'SELECT min(pair_count) fewest_pair_count FROM counts',{'algorithm':'Flight-row-weighted city pair average, symmetric city identity, Haversine km, all 7 bins','assumptions':['ranges are lower-bound bins','English city names used']});progress(id,'frozen');reveal(id)
